import 'package:flutter/foundation.dart';

import 'mss_catalog_bundle.dart';

/// Maps pre-2026 scheme ids (`SCH######`, `MSME2015-###`, legacy codes such as
/// `TN001`) to the 2026 ids (`CEN2026-###`, `TN2026-###`, `MAH2026-###`) so
/// saved, recently-viewed and eligibility-saved items survive the catalog
/// migration. The map is embedded in `catalog_bundle.json.gz` (section
/// `migrations.json`), generated by `tools/import_schemes_json.py`.
class SchemeIdMigration {
  SchemeIdMigration._();

  static Map<String, String>? _override;

  /// The id map of the loaded catalog bundle. A bundle that cannot be loaded
  /// yields an empty map: the migration is then a no-op instead of failing
  /// app start.
  static Future<Map<String, String>> load() async {
    final override = _override;
    if (override != null) return override;
    try {
      return (await MssCatalogBundle.load()).schemeIdMap;
    } catch (e) {
      debugPrint('[SchemeIdMigration] id map unavailable: $e');
      return const {};
    }
  }

  @visibleForTesting
  static void resetForTest([Map<String, String>? map]) => _override = map;

  /// Pre-2026 id shapes: `SCH######`, `MSME2015-###`, legacy codes `TN###` /
  /// `IN###`.
  static final RegExp _legacyShape = RegExp(
    r'^(SCH\d{6}|MSME2015-\d+|(TN|IN)\d{3})$',
    caseSensitive: false,
  );

  /// Rewrites [ids] through [idMap]. Ids already in [knownIds] are kept; a
  /// pre-2026 id that maps to a known id is replaced; a pre-2026 id whose
  /// scheme no longer exists is dropped. Any other unknown id is left alone,
  /// so a catalog that is merely missing an entry can never erase a user's
  /// saved item. Order is preserved and duplicates removed. Returns null when
  /// nothing changed.
  static List<String>? migrate(
    List<String> ids,
    Map<String, String> idMap,
    Set<String> knownIds,
  ) {
    final out = <String>[];
    final seen = <String>{};
    for (final id in ids) {
      String? target;
      if (knownIds.contains(id)) {
        target = id;
      } else {
        final mapped = idMap[id];
        if (mapped != null && knownIds.contains(mapped)) {
          target = mapped;
        } else if (!_legacyShape.hasMatch(id) && !idMap.containsKey(id)) {
          target = id; // not a pre-2026 id: not ours to remove
        }
      }
      if (target != null && seen.add(target)) out.add(target);
    }
    return listEquals(out, ids) ? null : out;
  }
}
